<?php require __DIR__.'/../app/bootstrap.php';require_login();require_permission('logistics.approve');verify_csrf();$id=(int)($_POST['id']??0);$decision=$_POST['decision']??'';$row=$pdo->prepare('SELECT * FROM logistics_orders WHERE id=?');$row->execute([$id]);$r=$row->fetch();if(!$r)redirect('../'.page_url('approvals'));$new=$decision==='approve'?'Disetujui':'Ditolak';$stmt=$pdo->prepare('UPDATE logistics_orders SET approval_status=?,approved_by=?,approved_at=NOW(),status=IF(?="Disetujui","Dipesan",status) WHERE id=?');$stmt->execute([$new,current_user()['id'],$new,$id]);add_history($pdo,'logistics_order',$id,$r['approval_status'],$new,'Keputusan approval spare part');audit($pdo,'APPROVE','logistics_order',$id,$new.' '.$r['item_name']);if($r['requested_by'])notify($pdo,(int)$r['requested_by'],'approval','Permintaan spare part '.$new,'Permintaan '.$r['request_no'].' untuk '.$r['item_name'].' '.$new,page_url('logistics'));flash('success','Keputusan approval berhasil disimpan.');redirect('../'.page_url('approvals'));
